'collagen-arthritis': {category:'Inflammation & Immunology', name:'Collagen-Induced Arthritis', eyebrow:'Chronic Anti-Inflammatory Activity · Autoimmune Model', principle:'Immunization with type II collagen induces an autoantibody-mediated polyarthritis that closely models human rheumatoid arthritis; arthritic score is scored across paws over weeks.', visual:'tray', animal:'🐀', type:'reading', unit:'arthritic score (0–16)', baseline:10, sd:1.5, decimals:1, cutoff:16, higherIsBetter:false, drugs:[{id:'saline',label:'Saline (control)',factor:1},{id:'methotrexate',label:'Methotrexate 1 mg/kg',factor:0.45},{id:'dexamethasone',label:'Dexamethasone 0.5 mg/kg',factor:0.4}]},
